def intersect(lists):
    lists.sort(key=len)                     # rarest first
    result, cursors = [], [iter_of(l) for l in lists]
    for d in cursors[0]:
        ok = True
        for c in cursors[1:]:
            c.advance_to(d)                  # uses skip list / block max
            if c.doc != d: ok = False; break
        if ok: result.append(d)
    return result

def search(q, k, shards, timeout=150ms, hedge_after=60ms):
    futures = {s: send(s.pick_replica(), q, k) for s in shards}
    at(hedge_after): for s,f in futures: if not f.done: f.add(send(s.other_replica(), q, k))
    results = wait_all(futures, timeout)      # first reply per shard wins
    heap = MinHeap(k)
    for top in results.values():
        for (doc, score) in top: heap.push_if_better(score, doc)
    partial = len(results) < len(shards)
    return heap.sorted_desc(), partial

def apply(evt):
    cur = shard.get_version(evt.doc_id)     # includes tombstone versions
    if cur is not None and evt.version <= cur:
        return 'skip-stale'
    if evt.op == 'delete': shard.tombstone(evt.doc_id, evt.version)
    else: shard.index(build_doc(evt), evt.version)
